// Checks the request really came from Convex, exactly as Convex's lib/signing.ts
// does the other way round: HMAC-SHA256 of "<timestamp>.<raw body>" with the shared
// secret, and a timestamp no more than 5 minutes from now.
const crypto = require('crypto');
const MAX_SKEW_SECONDS = 5 * 60;

const { headers } = $input.first().json;
// The raw bytes Convex signed. Re-serialising parsed JSON could change them.
const body = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const timestamp = headers['x-lendloop-timestamp'] ?? '';
const signature = headers['x-lendloop-signature'] ?? '';

const expected =
  'sha256=' +
  crypto.createHmac('sha256', $env.LENDLOOP_EVENTS_SECRET).update(`${timestamp}.${body}`).digest('hex');
const fresh =
  /^\d+$/.test(timestamp) && Math.abs(Date.now() / 1000 - Number(timestamp)) <= MAX_SKEW_SECONDS;
// Constant-time comparison; it needs equal lengths, and a wrong length is simply invalid.
const matches =
  signature.length === expected.length &&
  crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected));

return [{ json: { valid: fresh && matches, event: fresh && matches ? JSON.parse(body) : null } }];

// Convex retries reuse the event id. Ids of events already emailed are kept in this
// workflow's static data (stored with the workflow; production runs only).
const state = $getWorkflowStaticData('global');
const handled = state.handledEventIds ?? [];
const { event } = $input.first().json;
return [{ json: { event, duplicate: handled.includes(event.id) } }];

// One email per event, to the person who needs to act on it or know about it.
const { type, data } = $input.first().json.event;
const appUrl = $env.LENDLOOP_APP_URL;
const dates =
  data.startDate === data.endDate ? data.startDate : `${data.startDate} to ${data.endDate}`;
const declineReasons = {
  conflict: 'someone else was approved for those dates first',
  toolRemoved: 'the tool is no longer listed',
};

const emails = {
  'loan.requested': {
    recipient: 'lender',
    to: data.lender,
    subject: `${data.borrower.name} wants to borrow your ${data.toolName}`,
    text: `${data.borrower.name} asked to borrow your ${data.toolName} from ${dates}.\n\nApprove or decline: ${appUrl}/incoming`,
  },
  'loan.approved': {
    recipient: 'borrower',
    to: data.borrower,
    subject: `${data.lender.name} approved your request for the ${data.toolName}`,
    text: `You can borrow the ${data.toolName} from ${dates}. Arrange the pick-up with ${data.lender.name}.\n\nYour requests: ${appUrl}/requests`,
  },
  'loan.declined': {
    recipient: 'borrower',
    to: data.borrower,
    subject: `Your request for the ${data.toolName} was declined`,
    text:
      (data.declineReason
        ? `Your request for ${dates} was declined because ${declineReasons[data.declineReason]}.`
        : `${data.lender.name} can't lend the ${data.toolName} from ${dates}.`) +
      `\n\nFind something else: ${appUrl}/tools`,
  },
  'loan.cancelled': {
    recipient: 'lender',
    to: data.lender,
    subject: `${data.borrower.name} cancelled their request for your ${data.toolName}`,
    text: `The request for ${dates} was withdrawn. Nothing for you to do.\n\nIncoming requests: ${appUrl}/incoming`,
  },
  'loan.returned': {
    recipient: 'borrower',
    to: data.borrower,
    subject: `Thanks for returning the ${data.toolName}`,
    text: `${data.lender.name} marked the ${data.toolName} as returned. Thanks for looking after it.`,
  },
};

const email = emails[type];
if (!email) {
  throw new Error(`No email for event type ${type}`);
}
return [
  {
    json: {
      recipient: email.recipient,
      to: `${email.to.name} <${email.to.email}>`,
      subject: email.subject,
      text: `Hi ${email.to.name},\n\n${email.text}\n\nLendLoop`,
    },
  },
];

// Only reached after the email was sent, so a failed send is retried by Convex
// and not mistaken for a duplicate. Keeps the last 1000 ids.
const state = $getWorkflowStaticData('global');
const { id } = $('Skip repeats').first().json.event;
state.handledEventIds = [...(state.handledEventIds ?? []), id].slice(-1000);
return [{ json: { status: 'sent', eventId: id } }];

// Tells Convex the email went out, for the recipient's activity feed. The id comes
// from the event id, so if this report is ever repeated, Convex records it once.
const crypto = require('crypto');
const { event } = $('Skip repeats').first().json;
const { recipient } = $('Compose email').first().json;
const body = JSON.stringify({
  id: `email:${event.id}`,
  type: 'email.sent',
  loanId: event.loanId,
  recipient,
});
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature =
  'sha256=' +
  crypto.createHmac('sha256', $env.LENDLOOP_REQUESTS_SECRET).update(`${timestamp}.${body}`).digest('hex');
return [{ json: { body, timestamp, signature } }];
